<script setup>
import {ref,onMounted} from 'vue';import {supabase} from '../lib/supabase.js'
const loading=ref(true),error=ref(''),stats=ref({}),recent=ref([]),quant=ref(null)
const n=v=>Number(v||0).toLocaleString('zh-CN')
onMounted(async()=>{try{const [{data,error:e},{data:logs},q]=await Promise.all([supabase.rpc('get_admin_dashboard_summary'),supabase.from('admin_audit_logs').select('*').order('created_at',{ascending:false}).limit(6),fetch(`${import.meta.env.VITE_QUANT_API_URL||'http://127.0.0.1:8000'}/api/quant/pipeline/status`).then(r=>r.ok?r.json():null).catch(()=>null)]);if(e)throw e;stats.value=data||{};recent.value=logs||[];quant.value=q}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div class="page"><div v-if="error" class="notice">{{error}}</div><div v-if="loading" class="loading">正在汇总今日数据…</div><template v-else><section class="grid metrics"><article class="card metric"><span>开放功能</span><strong>{{n(stats.enabledFeatures)}}</strong><small>当前可访问模块</small></article><article class="card metric"><span>已发布文章</span><strong>{{n(stats.publishedPosts)}}</strong><small>前台公开内容</small></article><article class="card metric"><span>会员总数</span><strong>{{n(stats.members)}}</strong><small>经营会员档案</small></article><article class="card metric"><span>近24小时事件</span><strong>{{n(stats.events24h)}}</strong><small>{{n(stats.devices24h)}} 台设备</small></article></section><section class="grid two-col"><article class="card"><h3>运行概览</h3><div class="kpi-list"><div><span>慢方法 / 卡顿</span><b>{{n(stats.slow24h)}}</b></div><div><span>最新市场数据</span><b>{{stats.latestMarketDate||'暂无'}}</b></div><div><span>量化服务</span><b :class="['badge',quant?'':'warn']">{{quant?'在线':'离线'}}</b></div><div><span>覆盖股票</span><b>{{n(quant?.snapshot?.stockCount)}}</b></div></div></article><article class="card"><h3>最近操作</h3><div v-if="!recent.length" class="empty">暂无操作记录</div><div v-else class="kpi-list"><div v-for="item in recent" :key="item.id"><span>{{item.action}} · {{item.target_type}}</span><b>{{new Date(item.created_at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}}</b></div></div></article></section></template></div></template>
